/* generated by tools/build_offline_kb.py */
window.TM_OFFLINE_KB = {"v":1,"modules":[{"m":"M0","slug":"00-binet","title":"比奈方程（现有样板）","tags":["中心力","比奈方程","圆锥曲线","进动"],"summary":"本文从极坐标下的牛顿第二定律出发，利用中心力场中的角动量守恒， 引入变量 $u=1/r$，逐步推导出比奈方程（Binet equation）。随后将其应用于万有引力情形，证明行星轨道为圆锥曲线， 并讨论偏心率 $e$ 与轨道类型的关系。","href":"modules/00-binet/index.html","pdf":"modules/00-binet/binet.pdf"},{"m":"M1","slug":"01-effective-potential","title":"有效势与轨道稳定性","tags":["有效势","RK4","Bertrand","进动"],"summary":"用有效势方法分析中心力场中的圆轨道、稳定性、径向振动与进动，并以 RK4 数值积分验证解析结论。","href":"modules/01-effective-potential/index.html","pdf":"modules/01-effective-potential/note.pdf"},{"m":"M2","slug":"02-scattering","title":"散射与俘获","tags":["散射","截面","俘获","RK4"],"summary":"用散射实验与有效势垒分析中心力场中的散射角、微分散射截面与俘获截面，并以 RK4 数值积分验证解析结论。","href":"modules/02-scattering/index.html","pdf":"modules/02-scattering/note.pdf"},{"m":"M3","slug":"03-two-body","title":"两体问题与系外行星","tags":["两体","RV","多普勒","系外行星"],"summary":"用质心与约化质量方法分析两体开普勒运动，计算恒星摆动速度与多普勒频移，并以太阳-木星/地球系统验证系外行星径向速度法。","href":"modules/03-two-body/index.html","pdf":"modules/03-two-body/note.pdf"},{"m":"M4","slug":"04-variational","title":"变分原理与等时摆","tags":["变分","费马","等时摆","Snell"],"summary":"用变分原理导出折射定律与最短路径，证明摆线的等时性，并以数值积分验证等时性离散度。","href":"modules/04-variational/index.html","pdf":"modules/04-variational/note.pdf"},{"m":"M5","slug":"05-virtual-work","title":"虚功原理与静力学","tags":["虚功","静力学","梯子","平衡"],"summary":"用虚功原理与势能驻值法分析静力学平衡，计算梯子临界角，并以数值验证。","href":"modules/05-virtual-work/index.html","pdf":"modules/05-virtual-work/note.pdf"},{"m":"M6","slug":"06-collisions","title":"碰撞与变质量","tags":["碰撞","变质量","恢复系数","雨滴"],"summary":"用碰撞几何与变质量动力学分析光滑球碰撞、雨滴下落与弹性碰撞链，并以数值验证。","href":"modules/06-collisions/index.html","pdf":"modules/06-collisions/note.pdf"},{"m":"M7","slug":"07-rigid-body","title":"刚体几何与角动量","tags":["刚体","角动量","球壳","质心"],"summary":"用质心积分、角动量守恒与 Newton 球壳定理分析刚体几何与引力势。","href":"modules/07-rigid-body/index.html","pdf":"modules/07-rigid-body/note.pdf"},{"m":"M8","slug":"08-kinematics","title":"运动学与非线性振动","tags":["运动学","振动","Lorentz","脱离"],"summary":"用运动学与非线性振荡分析圆柱脱离、单摆周期修正、Lorentz 力与相对运动。","href":"modules/08-kinematics/index.html","pdf":"modules/08-kinematics/note.pdf"}],"faq":[{"q":"什么是有效势？为什么能判断圆轨道稳定性？","a":"有效势把角动量项并进势能：$V_{eff}(r)=V(r)+L^2/(2mr^2)$。圆轨道要求 $V_{eff}'(r_0)=0$；若 $V_{eff}''(r_0)>0$，小扰动以 $\\omega_r=\\sqrt{V_{eff}''/m}$ 振动，轨道稳定；若小于 0 则不稳定。到 M1 拖 E 与 L 看曲线就明白了。","m":"M1","sec":"有效势"},{"q":"伯特兰定理是什么？","a":"在所有束缚轨道都闭合的中心力势中，只有两种幂律势：$V\\propto -1/r$（引力）与 $V\\propto r^2$（弹簧）。频率比 $\\omega_r/\\omega_\\theta=\\sqrt{k+2}$；只有 k=-2 与 k=2 给出有理比。","m":"M1","sec":"伯特兰定理"},{"q":"水星近日点进动对应广义相对论的哪个修正项？","a":"GR 的最低阶修正是 $u^2$ 项：$u''+u=GM/h^2+3GM\\,u^2/c^2$，不是 $u^3$。真实水星进动约 $5.02\\times10^{-7}$ rad/圈。页面里的 $\\mu u^3$ 是唯象进动项，用来演示“椭圆不闭合”，不要把它当成 GR。","m":"M0","sec":"GR 修正"},{"q":"离心势垒是什么？","a":"有效势里的 $L^2/(2mr^2)$ 在中心附近形成一堵“墙”，L 越大墙越高。高斯势 $V=-e^{-r^2/2}$ 的势垒只在 $L<2\\sqrt2/e\\approx1.04$ 时存在；超过它，势垒消失，粒子直坠中心。","m":"M1","sec":"离心势垒"},{"q":"散射截面为什么有时显示无穷大？","a":"对 $k/r^2$ 这种长程势，再远的粒子也会被偏转；前向 $\\Theta\\to0$ 的 $1/\\Theta^3$ 峰使总截面发散，所以显示“无有限截面”。这是物理结论，不是程序错误。","m":"M2","sec":"俘获截面"},{"q":"两体问题怎么化成单体？","a":"用约化质量 $\\mu=m_1m_2/(m_1+m_2)$ 和相对坐标 $r=r_1-r_2$，两体就化为“一个假想粒子绕固定中心转”。开普勒第三定律里的质量要用总质量 $M_1+M_2$。","m":"M3","sec":"约化质量"},{"q":"系外行星的 K 和 Δλ 是什么？","a":"恒星也绕共同质心转。视向速度半振幅 $K=\\frac{M_2}{M_1+M_2}\\frac{2\\pi a}{P\\sqrt{1-e^2}}\\sin i$；$\\Delta\\lambda$ 是 500nm 星光的多普勒偏移。到 M3 拖大 M2，看恒星小圈和 K 一起变大。","m":"M3","sec":"视向速度"},{"q":"等时摆为什么等时？","a":"沿摆线（cycloid）摆动时周期与振幅无关，是严格等时；普通单摆只在小角度近似等时。M4 里有不同高度的小球同时到达的演示。","m":"M4","sec":"等时摆"},{"q":"最速降线为什么不是直线？","a":"直线最短，但下降慢；摆线（brachistochrone）让小球先快速获得速度，整体用时更短。“更短 ≠ 更快”正是变分法的魅力。","m":"M4","sec":"最速降线"},{"q":"虚功原理为什么能求平衡？","a":"约束力不做功。给系统一个符合约束的虚位移，平衡时总虚功 $\\delta W=0$，于是广义力 $Q=0$；不用解出所有约束力就能得到平衡条件。","m":"M5","sec":"虚功"},{"q":"梯子临界角怎么推？","a":"力平衡给出 $N_w=P/(2\\tan\\theta)$，摩擦临界 $f=\\mu P=N_w$，所以 $\\tan\\theta_{min}=1/(2\\mu)$。临界是摩擦饱和，不是势能 Hessian 奇异。","m":"M5","sec":"梯子"},{"q":"恢复系数是什么？e=0 会粘住吗？","a":"$e$ 是碰后沿连心线的分离速度与碰前接近速度之比。光滑球 $e=0$ 只让法向速度相等，切向仍保留，所以一般不会粘住：$\\beta=\\arctan(2\\tan\\alpha)-\\alpha$，只有正碰 $\\alpha=0$ 才 $\\beta=0$。","m":"M6","sec":"恢复系数"},{"q":"雨滴为什么越落越快？","a":"雨滴质量随时间增加（$r=r_0+\\lambda t$），重力持续加速；在“静止雨水”模型（$u=0$）下 $v\\sim gt/4$，没有终端速度。","m":"M6","sec":"雨滴"},{"q":"转动惯量是什么？","a":"$I=\\sum mr^2$，是“难不难被转起来”的量度，地位相当于平动里的质量；平行轴定理 $I=I_{cm}+md^2$。","m":"M7","sec":"转动惯量"},{"q":"甲虫绕环一圈为什么只转 180°？","a":"角动量守恒：甲虫相对环走一圈，环反向转 $\\pi$；甲虫的世界角是相对角加环转角，正好到对侧。M7 的甲虫模式可以看拖尾与角度读数。","m":"M7","sec":"甲虫"},{"q":"球壳内部为什么没有引力？","a":"均匀球壳内部各方向引力抵消，势为常数 $-GM/R$，场强为零；壳外才等效为全部质量集中在球心。","m":"M7","sec":"球壳"},{"q":"圆柱脱离角为什么总是 48.19°？","a":"脱离条件 $N=0$ 给出 $\\cos\\theta=2/3$，所以 $\\theta=\\arccos(2/3)=48.19^\\circ$，与质量、半径、g 都无关。","m":"M8","sec":"圆柱脱离"},{"q":"单摆周期为什么随振幅变大？","a":"大角度不是简谐，周期 $T\\approx T_0(1+\\theta_0^2/16+\\cdots)$，振幅越大周期越长；小角度才近似等时。","m":"M8","sec":"单摆"},{"q":"双摆为什么混沌？","a":"对初值极端敏感：两条几乎相同的释放轨迹会指数分离；能量仍守恒，但长期不可预测。M8 的双摆模式能直接看到分道扬镳。","m":"M8","sec":"双摆"},{"q":"洛伦兹力和洛伦兹变换有什么区别？","a":"洛伦兹力 $F=-e(E+v\\times B)$ 描述电荷受力；洛伦兹变换是狭义相对论里两个惯性系的时间/坐标换算。两者不是一回事。","m":"M8","sec":"Lorentz 力"},{"q":"学理论力学先看哪章？","a":"推荐顺序：M0 比奈 → M1 有效势 → M2 散射 → M3 两体 → M4 变分 → M5 虚功 → M6 碰撞 → M7 刚体 → M8 运动学。每章先读 intro，再拖主滑块，最后看 note.pdf。","m":"M0","sec":"学习路径"},{"q":"这些模拟用的是什么单位？","a":"多数是无量纲演示单位（如 $G=M=1$、$m=1$、$L=1$），方便看规律；真实单位的换算在 note.pdf 的数值例子里。","m":"M1","sec":"单位"},{"q":"为什么行星轨道是椭圆？","a":"平方反比引力下，比奈方程给出圆锥曲线：$e<1$ 椭圆、$e=1$ 抛物线、$e>1$ 双曲线。M0 改 λ/μ 可以看到轨道闭合与进动。","m":"M0","sec":"圆锥曲线"},{"q":"什么是掠面速度/开普勒第二定律？","a":"行星与中心连线单位时间扫过的面积 $dA/dt=L/(2m)$ 恒定，所以近心点快、远心点慢；这是角动量守恒的几何表述。","m":"M0","sec":"掠面速度"},{"q":"拉格朗日方程是什么？","a":"拉格朗日方程是 $\\frac{d}{dt}\\frac{\\partial L}{\\partial \\dot q}-\\frac{\\partial L}{\\partial q}=0$，其中 $L=T-V$。它从能量出发，自动处理约束，比逐個画受力更适合复杂系统；M4 的变分法就是它的来源。","m":"M4","sec":"拉格朗日方程"},{"q":"最小作用量原理是什么？","a":"系统真实运动使作用量 $S=\\int L\\,dt$ 取驻值（$\\delta S=0$）。对 $S$ 做变分就得到拉格朗日方程；这是分析力学的核心出发点。","m":"M4","sec":"最小作用量"},{"q":"费马原理是什么？","a":"光走“时间最短”的路径。把时间写成路径的泛函并取驻值，就得到折射定律 $n_1\\sin\\theta_1=n_2\\sin\\theta_2$；M4 的折射模式可以直接拖折射率看光线弯折。","m":"M4","sec":"费马原理"},{"q":"角动量守恒是什么？","a":"合外力矩为零时，角动量 $L$ 保持不变。中心力场中 $L=mr^2\\dot\\theta$ 恒定，所以行星近心点快、远心点慢——这就是开普勒第二定律。","m":"M0","sec":"角动量守恒"},{"q":"平行轴定理是什么？","a":"$I=I_{cm}+md^2$：绕任意平行轴的转动惯量，等于绕质心轴的转动惯量加上 $md^2$。M7 的球壳/圆盘模式会用到它。","m":"M7","sec":"平行轴定理"},{"q":"简谐振动和阻尼振动有什么区别？","a":"简谐：$x''+\\omega_0^2x=0$，等幅振荡；阻尼：$x''+2\\gamma x'+\\omega_0^2x=0$，振幅指数衰减。M8 的单摆大角度还会出现周期随振幅变长。","m":"M8","sec":"阻尼振动"},{"q":"伽利略变换和洛伦兹变换有什么区别？","a":"伽利略变换 $x'=x-Vt$ 是低速近似；洛伦兹变换在接近光速时修正时间与长度。M8 讲的是洛伦兹力 $F=-e(E+v\\times B)$，不要和洛伦兹变换混为一谈。","m":"M8","sec":"参考系变换"},{"q":"M6 的两个球为什么现在会碰上了？","a":"碰撞判定改用真实半径 $R$，并用二维法向冲量求解；视觉半径与物理半径一致，还加了 0.5s 接触停顿与闪光。打开 `?demo=contact` 可以直接看接触瞬间。","m":"M6","sec":"碰撞接触"},{"q":"球冠高度 h 为什么可以到 2R？","a":"切割平面距球心 $b=R-h$，$b$ 可以从 $R$ 变到 $-R$，所以 $h$ 的范围是 $[0,2R]$；$h>R$ 时球冠超过半球，$h=2R$ 就是整个球。M7 的滑块上限已按直径 2R 限制。","m":"M7","sec":"球冠"},{"q":"线上网页的 AI 为什么是离线？","a":"GitHub Pages 只有静态文件，没有 `/api` 后端。要完整 AI，请在本机运行 `bash tools/serve.sh`，再打开 http://127.0.0.1:8765/；静态站会保留“讲义检索 + 常见问题直答”。","m":"M1","sec":"部署"},{"q":"HUD 里的数字和单位怎么看？","a":"多数模拟用无量纲演示单位（如 $G=M=1$、$m=1$、$L=1$），方便看规律；HUD 标签已写成“中文 + 符号”，真实单位换算在 note.pdf 的数值例子里。","m":"M1","sec":"单位"},{"q":"最大偏转角 β_max 怎么来的？","a":"对 $\\beta=\\arctan(2\\tan\\alpha)-\\alpha$ 求极值，得 $\\tan^2\\alpha=(1-e)/2$。$e=0$ 时 $\\beta_{max}=19.47^\\circ$，$e=0.5$ 时约 $36.87^\\circ$。","m":"M6","sec":"最大偏转"},{"q":"俘获截面怎么理解？","a":"$\\sigma=\\pi b_c^2$ 是一张“有效靶面积”：瞄准距离 $b<b_c$ 的入射粒子都会被势场俘获。M2 可以切到俘获模式拖 b 看螺旋。","m":"M2","sec":"俘获截面"},{"q":"为什么轨道会进动？","a":"当势不是严格的 $1/r^2$（例如加了 $\\lambda u^2$ 或 $\\mu u^3$ 修正），轨道不再闭合，近心点每圈转过一个角度，这就是进动。M0 拖 λ/μ 可以直接看。","m":"M0","sec":"进动"},{"q":"诺特定理是什么？","a":"每种连续对称性对应一个守恒量：时间平移对应能量，空间平移对应动量，旋转对应角动量。讲义没有展开证明，但 M4 的变分法与 M7 的角动量守恒都用到了这个思想。","m":"M4","sec":"诺特定理"},{"q":"开普勒第一定律是什么？","a":"行星轨道是椭圆，太阳位于一个焦点上。它来自平方反比引力下的比奈方程；偏心率 $e<1$ 就是椭圆，$e=1$ 抛物线，$e>1$ 双曲线。","m":"M0","sec":"开普勒第一定律"},{"q":"开普勒第二定律是什么？","a":"行星与太阳连线单位时间扫过的面积恒定（掠面速度守恒），所以近心点快、远心点慢；本质是角动量守恒。","m":"M0","sec":"开普勒第二定律"},{"q":"开普勒第三定律是什么？","a":"$P^2=\\frac{4\\pi^2 a^3}{G(M_1+M_2)}$；太阳系里近似为 $T^2\\propto a^3$。两体问题里质量要用总质量 $M_1+M_2$。","m":"M3","sec":"开普勒第三定律"},{"q":"中心力是什么？","a":"力只沿径向（指向或背离中心），横向分力为零；因此角动量 $L=mr^2\\dot\\theta$ 守恒，轨道在一平面内，开普勒第二定律成立。","m":"M0","sec":"中心力"},{"q":"比奈方程是什么？","a":"把 $u=1/r$ 代入中心力径向方程得到 $u''+u=-F(1/u)/(m h^2u^2)$（$h=L/m$）。它把轨道形状与力律直接联系起来，是 M0 的主方程。","m":"M0","sec":"比奈方程"},{"q":"微分散射截面是什么？","a":"$d\\sigma/d\\Omega=(b/\\sin\\Theta)|db/d\\Theta|$：把“瞄准距离在 $b\\sim b+db$ 的粒子”映射到“散射到 $\\Theta\\sim\\Theta+d\\Theta$ 的立体角”，是散射实验的核心观测量。","m":"M2","sec":"微分散射截面"},{"q":"什么是混沌？","a":"确定性系统对初值极端敏感：两条几乎相同的轨迹会指数分离。双摆就是典型例子——能量仍守恒，但长期运动不可预测。M8 的双摆模式能直接看到两条轨迹分道扬镳。","m":"M8","sec":"混沌"},{"q":"Lorentz 力的漂移方向怎么判断？","a":"漂移速度 $v_d=E\\times B/B^2$，方向由右手定则给出。例如 $E=E\\hat y$、$B=B\\hat z$ 时 $\\hat y\\times\\hat z=\\hat x$，漂移沿 $+x$。M8 的 Lorentz 模式会画出电子轨迹。","m":"M8","sec":"Lorentz 漂移"},{"q":"什么是变质量系统？","a":"质量随时间变化的系统，方程是 $d(mv)/dt=F+u\\,dm/dt$，$u$ 是加入质量的绝对速度。雨滴取 $u=0$（静止雨水），得到 $v\\sim gt/4$。","m":"M6","sec":"变质量"},{"q":"相空间的分界线是什么？","a":"单摆相图里分隔“振荡”和“旋转”的临界轨道：$E=mgL$，对应刚好到达最高点 $\\theta=\\pi$ 且速度为零。$E<mgL$ 振荡，$E>mgL$ 旋转。","m":"M8","sec":"分界线"}],"glossary":[{"t":"有效势","d":"真实势能与角动量项 L²/2r² 合成的曲线，把二维轨道变成“小球沿曲线滚动”的一维问题。","m":"M1"},{"t":"离心势垒","d":"有效势里因角动量在中心附近凸起的部分，像一堵墙，拦着带角动量的粒子掉进中心。","m":"M1"},{"t":"掠面速度","d":"行星与中心连线单位时间扫过的面积；中心力场里它不变，这就是开普勒第二定律。","m":"M0"},{"t":"伯特兰定理","d":"所有束缚轨道都闭合的中心力势只有两种：牛顿引力（∝1/r²）与弹簧（∝r²）。","m":"M1"},{"t":"约化质量","d":"μ=m₁m₂/(m₁+m₂)：把两个天体互绕化成“一个假想粒子绕固定中心转”的换算质量。","m":"M3"},{"t":"恢复系数","d":"e＝碰后沿连心线的分离速度与碰前接近速度之比：e=1 完全弹性，e=0 碰后法向速度相同（不是粘住）。","m":"M6"},{"t":"虚功","d":"给系统一个符合约束的“想象中的”微小位移时各力做的功；总虚功为零即平衡。","m":"M5"},{"t":"广义力","d":"虚功 Q·δq 中与每个广义坐标配对的 Q：它推动这个坐标，但不必是牛顿意义上的力。","m":"M5"},{"t":"转动惯量","d":"I=Σmr²：物体“难不难被转起来”的量度，地位相当于平动里的质量。","m":"M7"},{"t":"等时摆","d":"周期与摆幅无关的摆：单摆只在小角度近似等时，沿摆线摆动则严格等时。","m":"M4"},{"t":"洛伦兹变换","d":"两个相对匀速运动的观测者之间换算时间与坐标的公式（注意与“洛伦兹力”是两回事）。","m":"M8"},{"t":"俘获截面","d":"σ=πb_c²：一张“有效靶面积”，入射粒子瞄准进来就必被势场俘获。","m":"M2"}],"chunks":[{"m":"M0","sec":"模块概览","t":"本文从极坐标下的牛顿第二定律出发，利用中心力场中的角动量守恒， 引入变量 $u=1/r$，逐步推导出比奈方程（Binet equation）。 随后将其应用于万有引力情形，证明行星轨道为圆锥曲线， 并讨论偏心率 $e$ 与轨道类型的关系。 最后说明如何通过修改比奈方程的源项参数， 在数值模拟中改变行星的运动轨迹。"},{"m":"M0","sec":"万有引力与圆锥曲线轨道","t":"对行星绕太阳运动，万有引力为 F_r(r) = -GMm{r^{2}} = -GMm u^{2}, 其中 $G$ 为引力常量，$M$ 为太阳质量，负号表示吸引力。 代入比奈方程 ： u''+u = -frac{m(-GMm u^{2})}{L^{2}u^{2}} = frac{GMm^{2}}{L^{2}} . 定义 p ≡ frac{L^{2}}{GMm^{2}} , 则方程化为常系数线性方程 boxed{ frac{d^{2}u}{dtheta^{2}} + u = (1)/(p) } 其通解为 u(theta) = (1)/(p) + Acostheta + Bsintheta , 其中 $A,B$ 为积分常数。令 A = (e)/(p)costheta_0, B = (e)/(p)sintheta_0 , 则 u(theta) = (1)/(p)[1+ecos(theta-theta_0)], 从而 r(theta) = (p)/(1+ecos(theta-theta_0)) 这正是圆锥曲线的极坐标方程，其中 $p$ 为半通径， $ege 0$ 为偏心率，$theta_0$ 为轨道近心点方向。"},{"m":"M0","sec":"角动量守恒","t":"对中心力场，力只沿径向，横向分力为零： F_theta = 0 . 由式 得 m(2dot rdottheta + rddottheta)=0 . 注意到 (d)/(dt)(r^{2}dottheta) = 2rdot rdottheta + r^{2}ddottheta = r(2dot rdottheta + rddottheta), 于是 (d)/(dt)(m r^{2}dottheta)=0 . 定义角动量 L ≡ m r^{2}dottheta = 常量. 由此可得角速度与半径的关系 dottheta = L{m r^{2}} . 这正是开普勒第二定律（面积定律）的微分形式。"},{"m":"M0","sec":"轨道类型与偏心率","t":"由式 可知，轨道类型完全由偏心率 $e$ 决定： toprule 偏心率 & 轨道类型 & 说明 midrule $e=0$ & 圆 & 半径 $r=p$ 的圆周运动 $0<e<1$ & 椭圆 & 行星、多数卫星的轨道 $e=1$ & 抛物线 & 临界逃逸轨道 $e>1$ & 双曲线 & 非束缚的散射轨道 bottomrule 对于椭圆轨道，半长轴 $a$ 与半通径 $p$ 满足 p = a(1-e^{2}), 近日点与远日点距离分别为 r_{min}=(p)/(1+e)=a(1-e), r_{max}=(p)/(1-e)=a(1+e). 偏心率与总能量 $E$ 的关系为 e = sqrt{1+frac{2E L^{2}}{G^{2}M^{2}m^{3}}} . 当 $E<0$ 时 $e<1$，轨道为椭圆；当 $E=0$ 时 $e=1$； 当 $E>0$ 时 $e>1$。这体现了能量对轨道束缚性质的判据。"},{"m":"M0","sec":"比奈方程的推导","t":"引入新变量 u ≡ (1)/(r), 即 r=(1)/(u). 记 $u'=(du)/(dtheta)$，$u''=frac{d^{2}u}{dtheta^{2}}$。 由链式法则与式 ， dot u = (du)/(dtheta)dottheta = u' dottheta , 而 dot r = -1{u^{2}}dot u = -u'{u^{2}}dottheta . 代入 $dottheta = (L)/(m)u^{2}$，得 dot r = -u'{u^{2}}·(L)/(m)u^{2} = -(L)/(m)u' . 对式 再求时间导数： ddot r = -(L)/(m)(d u')/(dt) = -(L)/(m)u''dottheta = -(L)/(m)u''·(L)/(m)u^{2}, 即 boxed{ ddot r = -frac{L^{2}}{m^{2}}u^{2}u'' } 同时 rdottheta^{2} = (1)/(u)((L)/(m)u^{2})^{2} = frac{L^{2}}{m^{2}}u^{3} . 将式 与式 代入径向方程 ： m(-frac{L^{2}}{m^{2}}u^{2}u'' - frac{L^{2}}{m^{2}}u^{3})=F_r , 整理得 -frac{L^{2}}{m}u^{2}(u''+u)=F_r . 两边同除以 $-frac{L^{2}}{m}u^{2}$，得到比奈方程： boxed{ frac{d^{2}u}{dtheta^{2}} + u = -m F_r(1/u){L^{2}u^{2}} } 其中 $F"},{"m":"M0","sec":"推广与数值模拟","t":"比奈方程的价值在于：给定任意中心力 $F_r(r)$， 都可以直接写出关于 $u(theta)$ 的轨道微分方程， 而不必求解含时的二维运动方程。若将源项作如下推广： frac{d^{2}u}{dtheta^{2}} + u = C + lambda u^{2} + mu u^{3}, C=frac{GMm^{2}}{L^{2}}, 则 $lambda,mu$ 分别代表对平方反比定律的二次、三次修正。 当 $lambda=mu=0$ 时回到牛顿引力，轨道为闭合圆锥曲线； 当修正项不为零时，轨道的近心点会随每圈转动， 形成进动（precession）或玫瑰线型轨道。 广义相对论对牛顿引力的最低阶修正给出 $u''+u=GM/h^{2}+3GM u^{2}/c^{2}$（其中 $h=L/m$）， 即 $lambda_{rm GR}=3GM/c^{2}$、$mu=0$；水星近日点进动为 $5.02×10^{-7} rad/orbit$ 量级。 为直观展示上述结论，配套的交互网页 index.html 对式 作四阶 Runge--Kutta 数值积分， 并实时绘制行星轨迹。用户可调参数包括 item $C$：中心引力强度（对应 $GMm^{2}/L^{2}$）； item $e$：初始偏心率（决定初始近心点距离）； item $lambda$：二次修正系数； item $mu$：三次修正系数（唯象的非广义相对论进动，其进动幅度远大于水星实际 $5.02×10^{-7} rad/orbit$）； item 动画速度与轨迹显示。"},{"m":"M0","sec":"极坐标下的运动方程","t":"设质量为 $m$ 的质点在中心力场中运动，其位置矢量用极坐标表示为 mathbf r = r mathbf e_r, 其中 $r$ 为径向距离，$theta$ 为极角。极坐标的单位矢量满足 mathbf e_r = dottheta mathbf e_theta, mathbf e_theta = -dottheta mathbf e_r . 对位置矢量求导，得到速度 mathbf v = mathbf r = dot r mathbf e_r + rdottheta mathbf e_theta . 再次求导，得到加速度 mathbf a = mathbf v = (ddot r - rdottheta^{2})mathbf e_r + (2dot rdottheta + rddottheta)mathbf e_theta . 因此，牛顿第二定律 $mmathbf a=mathbf F$ 在极坐标下的两个分量为 m(ddot r - rdottheta^{2}) &= F_r, m(2dot rdottheta + rddottheta) &= F_theta ."},{"m":"M1","sec":"模块概览","t":"用有效势方法分析中心力场中的圆轨道、稳定性、径向振动与进动，并以 RK4 数值积分验证解析结论。 无量纲约定：m=1，Kepler 强度 α=1，高斯势 V0=λ=1。中心力 F=F(r)e_r 保守，存在 V(r)。有效势 V_eff(r)=V_base(r)+L²/(2r²)+γ/r³ 其中 base 势与导数： - 开普勒：V=-1/r，dV/dr=1/r² - 谐振子：V=r²/2，dV/dr=r - 高斯：V=-e^{-r²}，dV/dr=2r e^{-r²} - 幂律：V=sgn(k) r^k，dV/dr=sgn(k) k r^{k-1}（β=sgn(k)） 导数与加速度： dV_eff/dr = dV_base/dr - L²/r³ - 3γ/r⁴ r̈ = -dV_eff/dr θ̇ = L/r² 积分：RK4，固定步长 DT=0.004（动画按速度缩放）。能量 E=½ṙ²+V_eff(r) 在 HUD 监控漂移。约束：扫描下限 R_MIN=0.05，扫描上限 R_SCAN=12；r>14 判逃逸，r<0.04 判奇异。"},{"m":"M1","sec":"作业映射","t":"sec:map 本模块覆盖以下作业题（题面为原文简述，记号与原文一致；公式均已在原文中给出或要求证明）： small toprule 来源 & 题面简述 & 核心知识点 & 对应小节 midrule 作业-2 Q1 & 判断 $F(r)=F(r)e_r$ 是否保守 & 保守力判据、旋度、环路做功 & sub:conservative 作业-2 Q2 & 线性力场 $F_i=sum_j a_{ij}x_j$（$a_{ij}$ 常数）：满足什么条件才有势能？求其势能 & 旋度为零 $Leftrightarrow$ 系数矩阵对称 & sub:conservative 作业-2 Q3 & 高斯势 $V=-V_0e^{-lambda^2r^2}$：(a) 给定 $L$ 何时存在稳定圆轨道；(b) 证明 $L$ 过大时不存在圆轨道，求允许的最大角动量 & 有效势极值与二阶判据、临界 $L$ & sub:veff--sub:gaussian 作业-2 Q4 & 幂律势 $V=beta r^k$：求圆轨道半径 $r_0$ 与径向振动频率 $omega_r$；设 $a=omega_r/omega_theta$，求 $a=1$ 与 $a=2$ 对应的势能 & 圆轨道、径向小振动、闭合条件 & sub:circular 作业-2 Q5 & 抛物线彗星近日点为地球轨道半径的 $1/n$：证其在地球轨道内停留时间为 $T_E(2(n+2))/(3pi n)√((n-1)/(2n))$，并证最长停留为 $(2)/(3pi)$ 年 & 面积定律、抛物线轨道几何 & sub:comet 作业-2 Q6 & 平"},{"m":"M1","sec":"数值验证","t":"各项的实验设置与要点： item $r_0$（牛顿法）：对 $V_{eff}'(r)=alpha/r^2-L^2/r^3=0$ 牛顿迭代（$alpha=1$，$L=1.2$，初值 $0.8$，8 步）， 残差 $|V_{eff}'(r_0)|=1.110×10^{-16}<10^{-9}$（机器精度）。 item $omega_r$（近圆轨道）：初始 $r(0)=r_0+delta$、$dot r(0)=0$， RK4 积分约 20 个径向周期，用抛物线顶点定位相邻 $r$ 极大， $omega_r=2pi/T_r$。Kepler（$r_0=L=alpha=1$）解析值 $sqrt{V_{eff}''(r_0)}=1$；高斯势（$r_0=1$， $L=√(2/e)$）解析值 $2/√(e)=1.2130613$。 两行偏差 $1.47×10^{-4}$、$7.21×10^{-5}$ 是有限振幅的 $O(delta^2)$ 修正（Kepler 行恰为 $frac32delta^2=1.5×10^{-4}$，见 sec:derive 节 的适用条件），不是积分误差。 item 频率比 $a$：幂律势取 $beta=1/k$、$L=1$、$r_0=1$ （此时 $omega_theta=1$），$delta=0.01$，积分 10 个径向周期， $a=2pi/Deltatheta$（$Deltatheta$ 为相邻远心点极角差）。 $k=-1$（Kepler）与 $k=2$（谐振子）的轨道对所有振幅严格闭合， 误差为机器精度 $10^{-13}$；$k=1$ 的 $8.2×10^{-"},{"m":"M1","sec":"讨论","t":"sec:discuss 极限行为。 $kto-2^+$ 时 $a=√(k+2)to0$：径向振动频率趋于零， 圆轨道趋于临界稳定（这与高斯势 $Lto L_{max}^-$ 时 $omega_rto0$、$r_0tosqrt2/lambda$ 的行为一致）。 $eto0$ 时进动公式 仍有限 （一阶 $gamma/r^3$ 进动与 $e$ 无关，与广义相对论进动仅依赖 $p$ 一致）。 彗星问题中 $nto1^+$ 时 $tto0$（掠射），$ntoinfty$ 时 $tto(sqrt2)/(3pi)T_E≈0.150 T_E$（径向往返极限，有限值）； $t_{max}=(2)/(3pi)T_E$ 在 $n=2$ 取得，是货真价实的内部极大。 误差来源。 三类偏差各有明确量级：(i) RK4 截断误差 $O(h^4)$——20 个周期能量漂移 $2.6×10^{-14}$；(ii) 周期测量的抛物线顶点误差 $O(h^2)$—— 被闭合轨道行的 $10^{-13}$ 水平证实；(iii) 模型本身的近似—— 小振动 $O(delta^2)$（Kepler 行 $1.47×10^{-4}≈frac32delta^2$） 与一阶摄动 $O(gamma)$（$gamma/r^3$ 行 $1.5×10^{-2}$， $gamma$ 减半偏差比 $1.983$）。数值验证的价值正在于把 (iii) 与 (i)(ii) 清楚地区分开。 与作业题的对照。 表 tab:numeric 覆盖了 sec:map 节全部 9 道题的核心结论： 作业-2 Q3 的 $L_{max}=2√(2mV_0"},{"m":"M1","sec":"模型与假设","t":"sec:model 考虑质量为 $m$ 的质点在中心力场中运动。以力心为原点建立平面极坐标 $(r,theta)$ （角动量守恒保证运动限于一个平面，见 sub:veff 小节）， 位矢 $r=re_r$，$e_r$ 为径向单位矢量， $e_theta$ 为横向单位矢量。基本假设与适用条件如下： item 有心力假设：$F=F(r)e_r$，力的大小只依赖 $r$。 这排除了各向异性与耗散性；何时这样的力存在势能，由 sub:conservative 小节的判据回答（作业-2 Q1/Q2）。 item 保守力假设：所考虑的力场在 $r>0$ 的单连通区域内旋度为零， 从而存在势能 $V(r)$，$F=-nabla V$。 力心处的奇点（如 $1/r$ 型势）不影响 $r>0$ 区域内的全部结论。 item 单位制：解析推导保留 $m$ 与各势参数（$alpha$、$beta$、$k$、$V_0$、$lambda$ 等）； 数值验证统一取无量纲约定 $m=1$、Kepler 强度 $alpha=1$、 高斯势 $V_0=lambda=1$ 等，表 tab:numeric 同此约定。 item 记号约定：自然对数的底记作 $e$，离心率记作 $e$； sub:circular 小节的 $a$ 是频率比 $omega_r/omega_theta$（作业-2 Q4 的记号）， sub:omegaratio、sub:virial 小节的 $a$ 是椭圆半长轴（作业-5 Q4 的记号）， 两处含义不同，各自在首次出现处重新定义；$T$ 表示动能（作业-5 Q4 记号）， 周期类量用 $T_"},{"m":"M1","sec":"位力定理与椭圆轨道的时间平均（作业-5 Q4）","t":"sub:virial 对周期为 $tau$ 的束缚运动，定义时间平均 $langle frangle≡frac1tauint_0^tau f dt$。 由 $bigllangle(d)/(dt) (mr·r)bigrrangle=0$ （周期函数全周期平均下导数的平均为零）得位力定理 2langle Trangle=bigllangler·nabla Vbigrrangle, 其中 $T=frac12mv^2$ 为动能（作业-5 Q4 记号）。对引力势 $V=-k/r$ （$k>0$）：$r·nabla V=k/r=-V$，故 $2langle Trangle=-langle Vrangle$。 $langle1/rrangle$ 用面积定律计算：$dt=(m/L)r^2 dtheta$， 轨道 （$p=a(1-e^2)$，半长轴 $a$、半短轴 $b=a√(1-e^2)$， 周期 $tau=2pi ab m/L$ 即面积除以面积速率），则 langlefrac1rrangle =(m/L)/(tau)int_0^{2pi} r dtheta =(1)/(2pi ab)·2pi p{√(1-e^2)} =(1)/(a), 其中用了标准积分 $int_0^{2pi}(dtheta)/(1+ecostheta)=2pi{√(1-e^2)}$ （$0le e<1$）。于是 langle Vrangle=-(k)/(a), langle Trangle=(k)/(2a), 2langle Trangle=-langle Vrangle, 位力定理得到验证，且 $E=langle Tra"},{"m":"M1","sec":"圆轨道、稳定性与径向小振动（作业-2 Q4）","t":"sub:circular 圆轨道 $r(t)≡ r_0$ 要求 $dot r=ddot r=0$，即 $V_{eff}$ 取驻值： V_{eff}'(r_0)=0, omega_theta≡dottheta=(L)/(mr_0^2), 其中 $omega_theta$ 为圆周运动角频率。给径向一个小扰动 $r=r_0+delta r$ （$|delta r|ll r_0$），把 中的 $V_{eff}$ 在 $r_0$ 处 泰勒展开保留到二阶： frac12mbigl(delta rbigr)^2 +frac12V_{eff}''(r_0)(delta r)^2 =E-V_{eff}(r_0), 即扰动以频率 boxed{ omega_r=sqrt{V_{eff}''(r_0)/m} } 绕 $r_0$ 简谐振动。这正是稳定条件 V_{eff}''(r_0)>0 的物理内容：$V_{eff}''(r_0)<0$ 时 左端第二项为负， 扰动按 $e^{|omega_r|t}$ 指数发散（不稳定）；$V_{eff}''(r_0)=0$ 为临界情形。 的适用条件是线性化 $|delta r|ll r_0$； 有限振幅的频率修正为 $O(delta^2)$（见 sec:numeric 节的数值证据）。 对幂律势 $V=beta r^k$（作业-2 Q4；$beta$、$k$ 为常数）： $V_{eff}'=beta k r^{k-1}-L^2/(mr^3)=0$ 给出圆轨道半径 r_0=((L^2)/(mkbeta))^{ (1)/(k+2)}, 要求 $kbeta>0$（势足够吸引，"},{"m":"M2","sec":"讨论","t":"sec:discuss 长程势的总截面发散。 $V=k/r^2$ 的总散射截面发散，是因为势的衰减慢于 $1/r$； 任何有限 $b$ 都被偏转。物理上需要截断（如原子屏蔽或有限靶尺寸）。 这与 Rutherford 散射（$V∝ 1/r$）不同：Coulomb 势的总截面也发散， 但微分散射截面在 $Thetato0$ 时 $sim 1/Theta^4$，比 $k/r^2$ 势的 $sim 1/Theta^3$ 更强。 俘获的物理意义。 $V=-alpha/r^4$ 在 $rto0$ 时 $Vto-infty$，粒子一旦越过势垒就螺旋坠入； $b_c$ 给出俘获的``靶面积''半径。这种势在原子/分子碰撞中出现 （如 van der Waals 吸引尾），俘获截面 $sigma∝ E^{-1/2}$， 能量越低俘获截面越大。 散射角与碰撞参数的关系。 给出 $Theta$ 随 $b$ 单调递减：$b=0$ 时 $Theta=pi$ （正碰回弹），$btoinfty$ 时 $Thetato0$（掠射）。微分散射截面 在 $Thetato0$ 处按 $1/Theta^3$ 发散（前向峰，源于长程势）， 在 $Theta=pi$ 处有限（背散射有限）。 与 Rutherford 散射的比较。 Coulomb 势 $V=alpha/r$ 的散射角为 $Theta=2arctan(alpha/(2Eb))$， 微分散射截面 $dsigma/dOmega=(alpha/(4E))^2/sin^4(Theta/2)$。 相比之下，$V=k/r^2$ 势的微分散射截面在 $Thetato0$"},{"m":"M2","sec":"散射的基本公式","t":"sub:scattering-basics 对中心力散射，粒子从无穷远处入射，能量 $E>0$，碰撞参数 $b$。 轨道在极坐标下由比奈方程描述。散射角 $Theta$（入射与出射渐近线夹角）由 积分公式给出： Theta = pi - 2int_{r_{min}}^{infty} b dr{r^2√(1-V(r)/E-b^2/r^2)}, 其中 $r_{min}$ 是转折点（最近距离），满足 $V_{eff}(r_{min})=E$。 截面的定义。 微分散射截面 $dsigma/dOmega$ 描述散射到立体角 $dOmega$ 中的粒子数占比。几何上，碰撞参数在 $[b,b+db]$ 环带内的粒子被散射到 $[Theta,Theta+dTheta]$ 角度范围， 因此 2pi b |db| = (dsigma)/(dOmega) 2pisinTheta |dTheta|, 即 。总散射截面 $sigma=int(dsigma/dOmega) dOmega$。 俘获截面。 对吸引势，若存在有效势垒且 $E>V_{eff,max}$，粒子越过势垒 到达 $r=0$（俘获）。临界碰撞参数 $b_c$ 满足 $E=V_{eff,max}$， 俘获截面为 $sigma=pi b_c^2$（圆盘面积）。 其中 $r_{min}$ 是转折点（最近距离），满足 $V_{eff}(r_{min})=E$，即 1-frac{V(r_{min})}{E}-b^2{r_{min}^2}=0. 微分散射截面定义为 (dsigma)/(dOmega) = (b)/(sinTheta)|(db)/(dT"},{"m":"M2","sec":"模块概览","t":"用散射实验与有效势垒分析中心力场中的散射角、微分散射截面与俘获截面，并以 RK4 数值积分验证解析结论。 无量纲约定：m=1，散射能量 E>0。 - 排斥势：V(r)=k/r²（k>0） - 吸引势：V(r)=-α/r⁴（α>0） 散射角：Θ = π(1 - 1/√(1+k/(Eb²))) 微分散射截面：dσ/dΩ = (k/E)·(1-x)/[π·x²·(2-x)²·sin(πx)]，x=Θ/π 俘获：b_c = (4α/E)^{1/4}，σ = 2π√(α/E)"},{"m":"M2","sec":"作业映射","t":"sec:map small toprule 来源 & 题面简述 & 核心知识点 & 对应小节 midrule 作业-3 Q2 & 质量为 $m$ 的粒子以能量 $E$ 入射，受到中心排斥势 $V=k/r^2$ 的散射； 碰撞参数为 $b$：(a) 求散射角与 $b$ 的关系；(b) 推导微分散射截面 $dsigma/dOmega$；(c) 求总散射截面 $sigma$ & 比奈方程、散射角、截面定义 & sub:scattering 作业-3 Q3 & 在势场 $V=-alpha/r^4$ 中运动，质量为 $m$，能量为 $E$； 存在临界碰撞参数 $b_c$，当 $b<b_c$ 时粒子不受势垒阻挡而越过有效势垒而``螺旋坠入''力心； 推导 $b_c$ 的表达式，以及计算对应的总俘获截面 $sigma$ & 有效势垒、俘获条件、截面 & sub:capture bottomrule"},{"m":"M2","sec":"吸引势 $V=-\\alpha/r^4$ 的俘获（作业-3 Q3）","t":"sub:capture 势能 $V(r)=-alpha/r^4$（$alpha>0$，吸引，短程奇异）。有效势 V_{eff}(r)=-(alpha)/(r^4)+(L^2)/(2mr^2) =-(alpha)/(r^4)+(Eb^2)/(r^2), 其中 $L=mv_0 b$、$E=frac12 mv_0^2$。 令 $u=1/r^2$，则 V_{eff}(u)=-alpha u^2+Eb^2 u, 这是 $u$ 的下开口抛物线，在 u_*=(Eb^2)/(2alpha) Longleftrightarrow r_*=√((2alpha)/(Eb^2)) 处取得极大值（有效势垒）： V_{eff,max} = -alpha((Eb^2)/(2alpha))^2 + Eb^2((Eb^2)/(2alpha)) = (E^2 b^4)/(4alpha). 俘获条件：粒子能量 $E$ 超过势垒，即 $E>V_{eff,max}$： E > (E^2 b^4)/(4alpha) Longleftrightarrow b^4 < (4alpha)/(E). 因此临界碰撞参数为 boxed{ b_c=((4alpha)/(E))^{1/4} } （作业-3 Q3 所求）。$b<b_c$ 时粒子越过势垒，$rto0$ 螺旋坠入力心（俘获）； $bge b_c$ 时粒子被势垒反射（散射）。 总俘获截面为圆盘面积： sigma=pi b_c^2 =pi√((4alpha)/(E)) =2pi√((alpha)/(E)) （作业-3 Q3 所求）。"},{"m":"M2","sec":"模型与假设","t":"sec:model 考虑质量为 $m$ 的质点在中心力场中运动。以力心为原点建立平面极坐标 $(r,theta)$。基本假设： item 有心力假设：$boldsymbol F=F(r)boldsymbol e_r$，力的大小只依赖 $r$。 item 保守力假设：力场在 $r>0$ 区域旋度为零，存在势能 $V(r)$， $boldsymbol F=-nabla V$。 item 单位制：解析推导保留 $m$、$k$、$alpha$、$E$ 等参数； 数值验证统一取无量纲约定 $m=1$、$k=1$、$alpha=1$、$E=1$。 item 散射设定：粒子从无穷远处入射，能量 $E>0$，碰撞参数 $bge0$； 入射方向为 $x$ 轴，力心在原点，轨道对 $x$ 轴对称。 item 俘获设定：吸引势 $V=-alpha/r^4$（$alpha>0$）， 粒子能量 $E>0$；有效势存在势垒，$b<b_c$ 时粒子越过势垒到达 $r=0$ （俘获），$bge b_c$ 时粒子被势垒反射（散射）。 item 小角/远场近似：散射角 $Theta$ 为入射与出射渐近线的夹角， $0leThetalepi$；$Theta=0$ 对应无偏转，$Theta=pi$ 对应正碰回弹。"},{"m":"M2","sec":"排斥势 $V=k/r^2$ 的散射（作业-3 Q2）","t":"sub:scattering 势能 $V(r)=k/r^2$（$k>0$，排斥）。有效势 V_{eff}(r)=(k)/(r^2)+(L^2)/(2mr^2) =(k+L^2/(2m))/(r^2). 利用 $L=mv_0 b$、$E=frac12 mv_0^2$，有 $L^2/(2m)=Eb^2$，故 V_{eff}(r)=(k+Eb^2)/(r^2). 转折点由 给出： r_{min}^2 = (k+Eb^2)/(E) = b^2+(k)/(E). 令 $kappa≡ k/E$。则 $r_{min}=√(b^2+kappa)$。 把 代入 。积分 I≡int_{r_{min}}^{infty} b dr{r^2√(1-(b^2+kappa)/r^2)}. 令 $u=(b^2+kappa)/r^2=r_{min}^2/r^2$，则 $dr=-r_{min}/(2u^{3/2}) du$， 当 $r=r_{min}$ 时 $u=1$，$rtoinfty$ 时 $uto0$： I = b{2r_{min}}int_0^1 du{√(u(1-u))} = b{2r_{min}} B (tfrac12,tfrac12) = pi b{2r_{min}}. 其中 $B(1/2,1/2)=pi$。于是 Theta = pi - 2I = pi(1-b{r_{min}}) = pi(1-1{√(1+k/(Eb^2))}). 是作业-3 Q2(a) 的答案：$Theta$ 随 $b$ 从 $pi$（正碰，$b=0$） 单调减到 $0$（$btoinfty$）。"},{"m":"M3","sec":"模块概览","t":"用质心与约化质量方法分析两体开普勒运动，计算恒星摆动速度与多普勒频移，并以太阳-木星/地球系统验证系外行星径向速度法。 两体系统：质量 M1（恒星）、M2（行星），间距 a。质心条件 M1 r1 = M2 r2，r1+r2=a。 r1 = M2/(M1+M2) · a r2 = M1/(M1+M2) · a 约化质量 μ = M1 M2/(M1+M2)。两体 Kepler 第三定律：ω² = G(M1+M2)/a³。 摆动速度 v1 = ω r1。多普勒频移 Δλ/λ = v/c。 无量纲单位：M☉=1、AU=1、yr=1，G=4π²。太阳-木星：M2=0.000954 M☉、a=5.20 AU。太阳-地球：M2=0.000003 M☉、a=1.00 AU。"},{"m":"M3","sec":"讨论","t":"sec:discuss 约化质量与等效单体问题。 两体问题通过质心分离与约化质量 $mu=M_1M_2/(M_1+M_2)$ 等价为单体中心力问题。这一技巧在天体力学、分子物理中广泛使用。 相对运动的轨道形状与单体 Kepler 问题相同，仅时间尺度由总质量决定。 质心在太阳表面之外。 木星引起的太阳摆动幅度 $r_1≈7.4×10^8 m>R_odot$， 太阳绕质心的轨道半径超过太阳半径，恒星的`` Reflex motion'' 可观。 类地行星的挑战。 地球信号 $sim0.09 m/s$，比太阳表面噪声 $sim1 m/s$ 小一个数量级，需要长时间积分与多普勒测量精度 $sim0.1 m/s$。 系外行星探测方法。 径向速度法（RV）是最成功的系外行星探测方法之一，发现了数千颗行星。 其精度要求随行星质量与轨道距离变化：热木星（$M_psim M_J$，$asim0.05 AU$） 信号 $sim 50 m/s$，地球类似行星信号 $sim 0.1 m/s$。 其他方法包括凌星法（transit）、直接成像、微引力透镜等。 径向速度曲线的形状。 对圆轨道，$v_r(t)$ 为正弦函数，振幅 $K=v_1$（）。对椭圆轨道， $v_r(t)$ 非正弦，振幅为 $K=(M_2)/(M_1+M_2)2pi a{P√(1-e^2)}sin i$。 实际观测中拟合 Kepler 轨道得到 $K$、$P$、$e$，再反推 $M_2sin i$（最小质量）， 不直接使用圆轨道公式 。 与作业题的对照。 表 tab:numeric 覆盖了作业题 (a)--(e) 的全部数值结果。 "},{"m":"M3","sec":"两体能量与 virial","t":"sub:energy2 两体系统的总能量（圆轨道）： E = -(GM_1M_2)/(2a). 动能 $T=frac12 M_1 v_1^2+frac12 M_2 v_2^2 =frac12 mu v_{rel}^2$， 势能 $V=-GM_1M_2/a$。virial 定理 $2langle Trangle=-langle Vrangle$ 成立。"},{"m":"M3","sec":"太阳--木星系统（作业题 (a)(b)(c)）","t":"sub:jupiter 给定：$M_odot=1.989×10^{30} kg$， $M_J=1.898×10^{27} kg$， $a_J=7.78×10^{11} m$， $P_J=11.86 yr=11.86×3.156×10^7 s$。 (a) 质心距离。 由 ： r_1=(M_J)/(M_odot+M_J) a_J =frac{1.898×10^{27}}{1.989×10^{30}+1.898×10^{27}}×7.78×10^{11} ≈ 7.42×10^8 m. 太阳半径 $R_odot=6.96×10^8 m$，比值 (r_1)/(R_odot)≈(7.42×10^8)/(6.96×10^8)≈1.07. $r_1>R_odot$：太阳质心在太阳表面之外，太阳绕质心的``摆动''幅度 超过太阳半径。 (b) 角速度与摆动速度。 由 ： omega=√((G(M_odot+M_J))/(a_J^3)) =(2pi)/(P_J)≈1.68×10^{-8} rad/s. 摆动速度 v_1=omega r_1≈1.68×10^{-8}×7.42×10^8 ≈ 12.5 m/s. (c) 多普勒位移。 取 $lambda=500 nm$，$v_1≈12.5 m/s$： Deltalambda=lambda(v_1)/(c) =500 nm×(12.5)/(3.0×10^8) ≈ 2.08×10^{-5} nm."},{"m":"M3","sec":"太阳--地球系统（作业题 (d)(e)）","t":"sub:earth 给定：$M_E=5.97×10^{24} kg$， $a_E=1.496×10^{11} m$，$P_E=1 yr$。 (d) 重算。 r_1=(M_E)/(M_odot+M_E) a_E ≈frac{5.97×10^{24}}{1.989×10^{30}}×1.496×10^{11} ≈ 4.49×10^5 m (449 km). omega=(2pi)/(P_E)≈1.99×10^{-7} rad/s, v_1=omega r_1≈ 0.089 m/s (8.9 cm/s). 与走路速度 $1.4 m/s$ 相比，地球引起的太阳摆动慢约 16 倍； 与蜗牛速度 $1.3 cm/s$ 相比，快约 7 倍。 一句话：地球拖动太阳的摆动速度仅 $9 cm/s$， 比人走路慢一个数量级，但比蜗牛快。 (e) 为什么需要 $0.1 m/s$ 精度。 item 信号本身仅 $sim 0.09 m/s$（地球），仪器噪声必须优于信号， 否则无法分辨。 item 太阳表面噪声（米粒组织、$p$ 模振荡等）量级 $sim 1 m/s$， 远大于地球信号，需要长时间平均与建模扣除。"},{"m":"M3","sec":"解析结果","t":"sec:result item 质心距离：$r_1=M_2 a/(M_1+M_2)$（）。 item 两体 Kepler：$omega^2=G(M_1+M_2)/a^3$（）。 item 摆动速度：$v_1=omega r_1$（）。 item 多普勒：$Deltalambda/lambda=v/c$（）。 item 木星：$r_1≈7.42×10^8 m$，$r_1/R_odot≈1.07$， $v_1≈12.5 m/s$，$Deltalambda≈2.08×10^{-5} nm$。 item 地球：$r_1≈4.49×10^5 m$，$v_1≈0.089 m/s$。"},{"m":"M3","sec":"椭圆轨道的两体修正","t":"sub:ellipse2 一般椭圆轨道：半长轴 $a$，离心率 $e$。两体 Kepler 第三定律仍为 $P^2=4pi^2 a^3/(G(M_1+M_2))$，与单体形式相同，仅 $Mto M_1+M_2$。 恒星到质心的最大距离为 $r_{1,max}=M_2 a(1+e)/(M_1+M_2)$。 径向速度半振幅为 $K=(M_2)/(M_1+M_2)2pi a{P√(1-e^2)}sin i$； 正弦形式 $v_r(t)=Ksin(2pi t/P+phi)$ 仅适用于圆轨道（$e=0$）， 一般椭圆轨道的 $v_r(t)$ 非正弦。 在固定 $M_1,M_2,a$ 与 $sin ineq0$ 下，$eto1$ 时 $Ktoinfty$ （形式上的牛顿极限）。"},{"m":"M4","sec":"模块概览","t":"用变分原理导出折射定律与最短路径，证明摆线的等时性，并以数值积分验证等时性离散度。 变分原理：物理路径使泛函 J[y]=∫L(x,y,y')dx 取驻值，Euler-Lagrange 方程 ∂L/∂y - d/dx(∂L/∂y')=0。 费马原理：光程时间 T=∫n(s)/c ds 取驻值 → Snell 定律 n1 sinθ1=n2 sinθ2。 最短路径：弧长 S=∫ds 取驻值 → 直线 y=kx+c。 等时摆：摆线 h=s²/(8a)，下滑时间 T=π√(a/g)，与释放位置无关。一般：h=Cs²，T0=π/(2√(2gC))。"},{"m":"M4","sec":"摆线的等时性（作业-6 Q3）","t":"sub:cycloid 摆线参数方程： x=a(theta-sintheta), h=a(1+costheta), 0lethetalepi, $h$ 为相对最低点（$theta=pi$）的竖直高度。弧长从最低点向上： s=int_theta^pi 2asin(t/2) dt =4acos(theta/2). 高度： h=a(1+costheta)=2acos^2(theta/2)=(s^2)/(8a). （作业-6 Q3(a)：$s=4acos(theta/2)$，$h=s^2/(8a)$） 能量守恒：从 $s_0$ 释放，到达 $s$ 时下降高度为 $h_0-h=(s_0^2-s^2)/(8a)$，故 v(s)=√(2g(h_0-h))=√((g)/(4a)) √(s_0^2-s^2). 下滑时间从 $s_0$ 到 $0$： T=int_0^{s_0}(ds)/(v(s)) =√((4a)/(g))int_0^{s_0}ds{√(s_0^2-s^2)} =√((4a)/(g))·(pi)/(2) =pi√((a)/(g)). $T$ 与 $s_0$ 无关，等时性得证（作业-6 Q3(c)）。"},{"m":"M4","sec":"最短路径（作业-6 Q2）","t":"sub:shortest 二维平面中，两点间最短路径使弧长泛函 S=int ds=int√(dot x^2+dot y^2) dt 取驻值。Euler-Lagrange 方程：$L=√(dot x^2+dot y^2)$， $partial L/partial x=0$，$partial L/partialdot x=dot x/√(dot x^2+dot y^2)$， $d/dt(partial L/partialdot x)=0$，故 $dot x/√(dot x^2+dot y^2)=const$。 同理 $dot y/√(dot x^2+dot y^2)=const$。两式相除：$dot y/dot x=const$， 即 $y=kx+c$，直线。 极坐标证明。 弧长 $ds=√(dot r^2+r^2dottheta^2) dt$。 Lagrange 方程对 $theta$：$partial L/partialtheta=0$（旋转对称）， 故 $partial L/partialdottheta=r^2dottheta/√(dot r^2+r^2dottheta^2)=const=h$。 这给出角动量守恒。结合径向方程，积分得 $rsin(theta-theta_0)=const$， 即直线的极坐标方程。"},{"m":"M4","sec":"费马原理与折射定律（作业-6 Q1）","t":"sub:fermat 光在介质中速度 $v=c/n$（$n$ 为折射率）。费马原理：光程时间 T=int (n(s))/(c) ds 取驻值。考虑两层介质界面（$y=0$），折射率 $n_1$（上）、$n_2$（下）。 路径从 $A=(x_1,y_1)$ 到 $B=(x_2,y_2)$，在界面点 $(x,0)$ 折射。 时间泛函 T(x)=(n_1)/(c)√((x-x_1)^2+y_1^2) +(n_2)/(c)√((x-x_2)^2+y_2^2). 驻值条件 $dT/dx=0$： (n_1)/(c)x-x_1{√((x-x_1)^2+y_1^2)} +(n_2)/(c)x-x_2{√((x-x_2)^2+y_2^2)}=0. 设入射角 $theta_1$、折射角 $theta_2$（均与法线夹角），则 n_1sintheta_1=n_2sintheta_2 即 Snell 折射定律。"},{"m":"M4","sec":"数值验证","t":"sec:numeric 全部数值实验由配套脚本 qa/numeric_check.py 完成（仅依赖 numpy）。 centering small toprule 物理量 & 解析值 & 数值值 midrule $T$（摆线，$a=1,g=1,s_0=1$） & $pi=3.14159$ & $3.14159$ $T$（摆线，$a=1,g=1,s_0=0.5$） & $pi=3.14159$ & $3.14159$ $T_0$（$C=1/8,g=1$） & $pi=3.14159$ & $3.14159$ $T_0$（$C=1/4,g=1$） & $pi/(2√(0.5))=2.221$ & $2.221$ bottomrule caption{数值验证汇总。全部数值取自 qa/numeric_check.py 的实际输出。} tab:numeric"},{"m":"M4","sec":"作业映射","t":"sec:map small toprule 来源 & 题面简述 & 核心知识点 & 对应小节 midrule 作业-6 Q1 & 用费马原理和变分法证明折射定律 & 泛函变分、Snell 定律 & sub:fermat 作业-6 Q2 & 二维平面内，极坐标证明直线距离最短 & 测地线、Euler--Lagrange & sub:shortest 作业-6 Q3 & 摆线：$s=4acos(theta/2)$，$h=s^2/(8a)$； 从 $s_0$ 释放，证明下滑时间与 $s_0$ 无关 & 等时摆、时间积分 & sub:cycloid 作业-6 Q3(d) & 若 $h=C s^2$，证明时间仍与 $s_0$ 无关，求 $T_0$ 与 $C$ 的关系 & 一般等时条件 & sub:general bottomrule"},{"m":"M4","sec":"一般等时条件（作业-6 Q3(d)）","t":"sub:general 若高度满足 $h(s)=C s^2$（$C>0$），则下降高度 $h_0-h=C(s_0^2-s^2)$， 速度 $v(s)=√(2gC(s_0^2-s^2))$，下滑时间 T_0=int_0^{s_0}ds{√(2gC(s_0^2-s^2))} =1{√(2gC)}·(pi)/(2) =pi{2√(2gC)}. $T_0$ 与 $s_0$ 无关。与摆线对应：$C=1/(8a)$ 时 $T_0=pi/(2√(2g/(8a)))=pi√(a/g)$，与 Q3(c) 一致。"},{"m":"M5","sec":"模块概览","t":"用虚功原理与势能驻值法分析静力学平衡，计算梯子临界角，并以数值验证。 虚功原理：平衡时 δW=0。保守系统 δV=0（势能驻值）。 梯子临界角：tan θ_min = 1/(2μ)。μ 增大时 θ_min 减小。 弹簧杆：势能 V(θ) = -Pl/2 sinθ + ½k(BC-l0)²，平衡 dV/dθ=0。"},{"m":"M5","sec":"解析结果","t":"sec:result item 虚功原理：$delta W=0$，保守系统 $delta V=0$（、）。 item 梯子临界角：$tantheta_{min}=1/(2mu)$（）。 item 弹簧杆平衡：$dV/dtheta=0$（sub:spring-rod）。 item 圆柱平衡：$phi=0$（底部，稳定）。"},{"m":"M5","sec":"稳定性的判定","t":"sub:stability 平衡稳定 iff 势能 Hessian 矩阵正定： (partial^2 V)/(partial q_ipartial q_j)bigg|_{rm eq} succ 0. 注意：梯子靠摩擦维持平衡，临界状态是摩擦饱和 $f=mu N$，不是势能 Hessian 奇异；势能 $V=P(l/2)sintheta$ 在该处并没有极小。"},{"m":"M5","sec":"圆槽中的两圆柱（作业-7 Q3）","t":"sub:cylinders 半径 $R$ 的光滑圆槽，两圆柱半径 $r$，重量 $P_1$、$P_2$。 两柱相切且都与槽相切时，几何关系固定： sinphi=(r)/(R-r), 其中 $phi$ 为每柱中心与槽底方向的夹角。两柱作为整体还可绕槽心转动角度 $alpha$， 势能 $V=-(P_1+P_2)(R-r)cosphicosalpha$ 在 $alpha=0$ 取极小， 故平衡时两柱关于槽底对称；$phi$ 由几何决定，不能由 $dV/dphi=0$ 定出 （$phi=0$ 意味着两柱中心重合，几何上不可能）。 对等重 $P_1=P_2=P$ 的情形，单柱径向平衡给出 N=Pcosphi+Fsinphi, F=Ptanphi Longrightarrow N=(P)/(cosphi). $P_1ne P_2$ 时接触力不再水平，需联立两柱的径向与切向平衡消去 $F$ 后求 $N_1,N_2$。"},{"m":"M5","sec":"数值验证","t":"sec:numeric 全部数值实验由配套脚本 qa/numeric_check.py 完成（仅依赖 numpy）。 centering small toprule 物理量 & 解析值 & 数值值 midrule $theta_{min}$（$mu=0.5$） & $arctan(1)=45.0^circ$ & $45.0^circ$ $theta_{min}$（$mu=0.25$） & $arctan(2)=63.4^circ$ & $63.4^circ$ $theta_{min}$（$mu=1.0$） & $arctan(0.5)=26.6^circ$ & $26.6^circ$ bottomrule caption{数值验证汇总。全部数值取自 qa/numeric_check.py 的实际输出。} tab:numeric"},{"m":"M5","sec":"弹簧杆平衡（作业-7 Q5）","t":"sub:spring-rod 杆 AB 长 $l$，重量 $P$，铰链 A，弹簧连接 B 与 C（C 在 A 上方 $h$ 处）。 设杆与水平线夹角 $theta$（$theta>0$ 表示 B 在 A 上方）。 势能（$theta>0$ 表示 B 在 A 上方，故重力势为正）： V(theta)=+(Pl)/(2)sintheta+frac12 k(L-l_0)^2, L=√(h^2+l^2-2hlsintheta). 平衡：$dV/dtheta=0$： (Pl)/(2)costheta + k(L-l_0)(-hlcostheta)/(L)=0. 非竖直平衡（$costhetane0$）条件： (P)/(2)=k(L-l_0)(h)/(L). 竖直平衡（$theta=pi/2$）始终存在。"},{"m":"M5","sec":"约束与自由度","t":"sec:constraints 一个含 $N$ 质点的系统有 $3N$ 个自由度。每个约束减少一个自由度。 完整约束（位置约束）：$f(boldsymbol r_i,t)=0$，减少 1 个自由度。 非完整约束（速度约束）：$sum a_i·dboldsymbol r_i=0$， 减少自由度但不减少坐标数。虚功原理适用于所有约束。 完整约束的分类。 固定端约束：质点位置固定（3 个约束）。 刚体约束：两点间距离固定（1 个约束）。 曲面约束：质点在曲面上运动（1 个约束）。 自由度计数。 单摆：1 个质点，1 个约束（绳长），自由度 $3-1=2$（平面运动）或 $1$（平面内）。 双摆：2 个质点，2 个约束，自由度 $6-2=4$（平面内 2）。"},{"m":"M6","sec":"模块概览","t":"用碰撞几何与变质量动力学分析光滑球碰撞、雨滴下落与弹性碰撞链，并以数值验证。 光滑球碰撞：法向恢复系数 e，切向无摩擦。偏转角 β，最大偏转角条件 tan²α=(1-e)/2。 变质量雨滴：dr/dt=λ=const，v(t)=g/(4λ)[(r0+λt)-r0⁴/(r0+λt)³]，t→∞ 时 v gt/4。 弹性碰撞链：m2≪m1 时，B2 反弹高度 H≈4h。"},{"m":"M6","sec":"数值验证","t":"sec:numeric 全部数值实验由配套脚本 qa/numeric_check.py 完成（仅依赖 numpy）。 centering small toprule 物理量 & 解析值 & 数值值 midrule $beta_{max}$（$e=0.5$） & $36.9^circ$ & $36.8699^circ$ $v(t)$（雨滴，$t=10$） & 公式值 & 数值积分一致 $H/h$（碰撞链） & $4.0$ & $4.0$ bottomrule caption{数值验证汇总。全部数值取自 qa/numeric_check.py 的实际输出。} tab:numeric"},{"m":"M6","sec":"附录：碰撞公式汇总","t":"sec:appendix item 一维弹性碰撞：$v_1'=(m_1-m_2)v_1/(m_1+m_2)$，$v_2'=2m_1 v_1/(m_1+m_2)$。 item 二维光滑球碰撞：法向恢复系数 $e$，切向不变。 item 变质量方程：$d(mv)/dt=F+dot m u$。 item 雨滴：$r=r_0+lambda t$，$v=g/(4lambda)[(r_0+lambda t)-r_0^4/(r_0+lambda t)^3]$。 item 碰撞链：$H=4h$（$m_2ll m_1$）。"},{"m":"M6","sec":"解析结果","t":"sec:result item 球碰撞偏转角：$cosbeta$ 公式（sub:collision）， $beta_{max}$ 时 $tan^2alpha=(1-e)/2$（）。 item 雨滴速度：$v(t)=(g)/(4lambda)[(r_0+lambda t)-r_0^4/(r_0+lambda t)^3]$ （），$ttoinfty$ 时 $vsim gt/4$。 item 弹性碰撞链：$H≈ 4h$（$m_2ll m_1$）。"},{"m":"M6","sec":"碰撞与变质量的应用","t":"sec:applications 台球游戏。 台球碰撞是完全弹性碰撞（$e≈1$）的日常例子。 碰撞角、偏转角的计算可预测台球轨迹。 火箭推进。 火箭是变质量系统（$dm/dt<0$），推力 $F=-dot m u$。 Tsiolkovsky 公式：$Delta v=uln(m_0/m_f)$。 雨滴增长。 雨滴下落时质量增长，速度增长慢于自由落体（$vsim gt/4$ vs $gt$）。"},{"m":"M6","sec":"弹性碰撞链（作业-5 Q3）","t":"sub:chain 球 B1 质量 $m_1$，B2 质量 $m_2$（$m_2ll m_1$）。B1 从高度 $h$ 落下， 与地面弹性碰撞后上升速度 $v_1=√(2gh)$，再与 B2（静止）弹性碰撞。 一维弹性碰撞公式： v_2'=(2m_1)/(m_1+m_2)v_1≈ 2v_1 (m_2ll m_1). B2 反弹高度 H=(v_2'^2)/(2g)≈(4v_1^2)/(2g)=4h. H≈ 4h"},{"m":"M6","sec":"雨滴变质量运动（作业-5 Q2）","t":"sub:raindrop 雨滴半径 $r$，质量 $m=rhofrac43pi r^3$。质量增加率与表面积成正比： (dm)/(dt)=k· 4pi r^2. 另一方面 $dm/dt=rho· 4pi r^2 dot r$，故 $dot r=k/rho=lambda$（常数）。 所以 $r(t)=r_0+lambda t$。 变质量牛顿方程（增加质量初速度为 0）： (d(mv))/(dt)=mg Longrightarrow mdot v+vdot m=mg Longrightarrow dot v=g-(vdot m)/(m). $dot m/m=3lambda/(r_0+lambda t)$，故 dot v+(3lambda)/(r_0+lambda t)v=g. 积分因子 $mu=(r_0+lambda t)^3$： (d)/(dt)[v(r_0+lambda t)^3]=g(r_0+lambda t)^3. 积分（$v(0)=0$）： v(t)=(g)/(4lambda)[(r_0+lambda t)-(r_0^4)/((r_0+lambda t)^3)] 当 $ttoinfty$，$vto gt/4$（线性增长）。"},{"m":"M7","sec":"模块概览","t":"用质心积分、角动量守恒与 Newton 球壳定理分析刚体几何与引力势。 球冠质心：d=(R-b)(3R+b)/[4(2R+b)]。半球 (b=0): d=3R/8。 甲虫-圆环：角动量守恒，环转角 π (180°)。 圆盘角动量：L=½MR²ω。 Newton 球壳：r<R 时 V=-GMm/R（常数），r>R 时 V=-GMm/r。"},{"m":"M7","sec":"讨论","t":"sec:discuss 角动量守恒的普遍性。 甲虫-圆环问题是角动量守恒的经典演示。系统初始角动量为零， 甲虫运动时环反向旋转，保持总角动量为零。 Newton 球壳定理的意义。 球壳定理是 Newton 万有引力理论的基石，解释了为什么行星可视为质点， 以及为什么球壳内部引力为零。 球冠质心的应用。 球冠质心公式用于计算球形天体（如行星、恒星）的引力势与转动惯量。 Newton 球壳定理的应用。 球壳定理解释了为什么行星内部（r<R）引力随 r 线性增加（$g∝ r$）， 而外部（r>R）按 $1/r^2$ 衰减。 与作业题的对照。 表 tab:numeric 覆盖了作业-4 Q1--Q4 的全部数值结果。 goldstein H. Goldstein, C. P. Poole, J. L. Safko, Classical Mechanics, 3rd ed., Pearson, 2002. （刚体、角动量、引力势。） newton I. Newton, Principia Mathematica, 1687. （球壳定理。） zhou 周衍柏，《理论力学教程》（第三版），高等教育出版社，2009. （刚体几何与角动量。）"},{"m":"M7","sec":"Newton 球壳定理的证明概要","t":"sec:shell-proof 球壳定理的证明利用高斯定律类比：引力场 $boldsymbol g$ 的通量 $oint boldsymbol g·dboldsymbol A=-4pi GM_{rm enc}$。 壳内 $M_{rm enc}=0$，故 $boldsymbol g=0$；壳外 $M_{rm enc}=M$， 故 $boldsymbol g=-GM/r^2 boldsymbol e_r$。"},{"m":"M7","sec":"Newton 球壳定理（作业-4 Q4）","t":"sub:shell 质量为 $M$ 的均匀球壳，半径 $a$。质点质量 $m$ 在距中心 $r$ 处。 壳内（$r<a$）： 引力势能为常数： V=-(GMm)/(a). 引力为零。 壳外（$r>a$）： 等效于质量 $M$ 集中于中心： V=-(GMm)/(r). 球壳表面（$r=a$）： $V=-GMm/a$，与壳内连续。"},{"m":"M7","sec":"转动惯量与平行轴定理","t":"sec:parallel-axis 平行轴定理：$I=I_{rm cm}+Md^2$，其中 $d$ 为新轴到质心轴的距离。 对圆盘：$I_{rm cm}=frac12 MR^2$（中心轴），$I_{rm edge}=I_{rm cm}+MR^2=frac32 MR^2$（边缘轴）。"},{"m":"M7","sec":"作业映射","t":"sec:map small toprule 来源 & 题面简述 & 核心知识点 & 对应小节 midrule 作业-4 Q1 & 球冠质心（球冠高度 $h$） & 质心积分、几何 & sub:spherical-cap 作业-4 Q2 & 甲虫在光滑圆环上爬行，环转角 & 角动量守恒、约束 & sub:beetle 作业-4 Q3 & 薄圆盘绕中心轴角动量 & 转动惯量、角动量 & sub:disk 作业-4 Q4 & 球壳对质点的引力势能 & Newton 球壳定理 & sub:shell bottomrule"},{"m":"M7","sec":"甲虫与圆环（作业-4 Q2）","t":"sub:beetle 圆环质量 $m$，半径 $R$，甲虫质量 $m$。系统初始静止。 甲虫在环上逆时针爬行，速度 $u$（相对环）。设环角速度 $Omega$（顺时针为正， 即甲虫相对环运动方向为正时环旋转为负）。 角动量守恒（无外力矩）： 0 = mR(u-Omega R?) + I_{rm ring}Omega. 设甲虫相对环的速度为 $v$（切向，逆时针为正），环角速度为 $omega$（逆时针为正）。 甲虫惯性系速度 $=v+omega R$（切向）。甲虫角动量 $=mR(v+omega R)$。 环角动量 $=mR^2omega$（薄环转动惯量 $mR^2$）。 mR(v+omega R)+mR^2omega=0 Longrightarrow v+2omega R=0 Longrightarrow omega=-(v)/(2R). 环以角速度 $v/(2R)$ 顺时针旋转。甲虫相对环走一圈（$2pi R$）耗时 $T=2pi R/v$。环转角 Deltatheta=|omega|T=(v)/(2R)·(2pi R)/(v)=pi 即环转 $180^circ$（$pi$ 弧度）。"},{"m":"M8","sec":"模块概览","t":"用运动学与非线性振荡分析圆柱脱离、单摆周期修正、Lorentz 力与相对运动。 圆柱脱离：cos θ = 2/3，θ ≈ 48.19°。 单摆周期：T ≈ 2π√(L/g)(1 + θ0²/16)。 Lorentz 力：回旋半径 r = mv/(eB)，漂移 v_d = E×B/B²。"},{"m":"M8","sec":"极坐标运动学","t":"sec:polar-kinematics 极坐标 $(r,theta)$ 中的速度与加速度： boldsymbol v = dot r boldsymbol e_r + rdottheta boldsymbol e_theta, boldsymbol a = (ddot r-rdottheta^2) boldsymbol e_r + (rddottheta+2dot rdottheta) boldsymbol e_theta. 作业-1 Q1 的椭圆交点速度即用此公式计算。"},{"m":"M8","sec":"讨论","t":"sec:discuss 非线性振荡的重要性。 单摆周期的振幅修正 $theta_0^2/16$ 是非线性效应的体现。 大振幅时需用椭圆积分精确计算。 Lorentz 力的应用。 回旋运动与 $boldsymbol E×boldsymbol B$ 漂移是等离子体物理、 加速器物理的基础。 圆柱脱离的物理解释。 质点在圆柱上滑动时，法向力 $N=mgcostheta-mv^2/R$。 当 $N=0$ 时脱离，即 $mgcostheta=mv^2/R$。 结合能量守恒 $v^2=2gR(1-costheta)$，得 $costheta=2/3$。 单摆的非线性效应。 大振幅单摆周期比小振幅长。振幅 $theta_0=90^circ$ 时， 周期增加约 $18 与作业题的对照。 表 tab:numeric 覆盖了作业-1 Q4--Q6 的核心结论。 goldstein H. Goldstein, C. P. Poole, J. L. Safko, Classical Mechanics, 3rd ed., Pearson, 2002. （运动学与非线性振动。） jackson J. D. Jackson, Classical Electrodynamics, 3rd ed., Wiley, 1999. （Lorentz 力。） zhou 周衍柏，《理论力学教程》（第三版），高等教育出版社，2009. （运动学与振动。）"},{"m":"M8","sec":"圆柱脱离（作业-1 Q6）","t":"sub:cylinder 质点从圆柱顶部（$r=R$）静止滑下，圆柱光滑。设滑下角度为 $theta$（从顶点量）。 能量守恒：$frac12 mv^2=mgR(1-costheta)$，故 $v^2=2gR(1-costheta)$。 径向牛顿方程（向心为正）： mgcostheta - N = (mv^2)/(R). 脱离条件 $N=0$： gcostheta = (v^2)/(R) = 2g(1-costheta) Longrightarrow 3costheta=2 Longrightarrow costheta=frac23, theta=arccosfrac23≈48.2^circ"},{"m":"M8","sec":"相空间与非线性振荡","t":"sec:phase-space 单摆相空间：$(theta,dottheta)$ 平面。小振幅：椭圆（简谐）。 大振幅：扭曲的闭合曲线。分界线（separatrix） separates 振荡与旋转。 能量 $E=frac12 m L^2 dottheta^2 - mgLcostheta$。 $E<-mgL$ 不允许；$-mgL<E<mgL$：振荡；$E>mgL$：旋转；$E=mgL$：分界线（过最高点 $theta=pi$ 的临界轨道）。"},{"m":"M8","sec":"Lorentz 力（作业-1 Q4）","t":"sub:lorentz 电子在相互垂直的匀强 $boldsymbol E$、$boldsymbol B$ 场中， 初速度 $boldsymbol vperpboldsymbol E,boldsymbol B$。 Lorentz 力 $boldsymbol F=-e(boldsymbol E+boldsymbol v×boldsymbol B)$。 设 $boldsymbol E=Ehat y$，$boldsymbol B=Bhat z$，$boldsymbol v=(v_0,0,0)$。 运动方程：$mboldsymbol v=-e(boldsymbol E+boldsymbol v×boldsymbol B)$。 $x$-$y$ 平面：$mdot v_x=-eB v_y$，$mdot v_y=-eE+eB v_x$。 解为回旋运动叠加 $boldsymbol E×boldsymbol B$ 漂移： boldsymbol v_d=(boldsymbol E×boldsymbol B)/(B^2). 回旋半径 $r_c=mv_perp/(eB)$，回旋频率 $omega_c=eB/m$。"},{"m":"M8","sec":"相对运动与伽利略变换","t":"sec:relative-motion 伽利略变换：$boldsymbol r'=boldsymbol r-boldsymbol V t$， $boldsymbol v'=boldsymbol v-boldsymbol V$，$boldsymbol a'=boldsymbol a$。 作业-1 Q3 的渡河问题即相对运动的应用：船对地速度 = 船对水速度 + 水对地速度。 渡河最短时间。 船相对水速度 $v_2$，水流速度 $v_1$。最短渡河时间 $T=d/v_2$（垂直渡河）， 设船头与河岸法线夹角为 $theta$，则渡河时间 $T=d/(v_2costheta)$， 沿河漂移 $x=(v_1-v_2sintheta)T$。对 $theta$ 求极小，当 $v_1>v_2$ 时 x_{min}=(d)/(v_2)√(v_1^2-v_2^2). 例如 $v_1=2, v_2=1$ 时 $x_{min}=sqrt3 d≈1.732d$， 而不是垂直船头时的 $d v_1/v_2=2d$。"}]};
